# Reusable parametrize args
_PARAM_CASES = _ENDPOINT_DATA
_PARAM_IDS = _param_ids(_ENDPOINT_DATA)

@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
@pytest.mark.smoke
def test_delete_order(api_client, scenario_case, config_test_data):
    """
    Test DELETE /store/order/{orderId} endpoint with various scenarios.

    This test covers:
    - Successful deletion of an order
    - Handling of invalid order IDs
    - Order not found scenario
    """

    endpoint = f"/store/order/{scenario_case['orderId']}"
    expected_status_code = scenario_case.get('statusCode', 200)
    
    # Validate request before sending
    swagger_validator.validate_json({'orderId': scenario_case['orderId']}, 'OrderId')

    # Perform DELETE request
    response = api_client.delete(endpoint)

    # Validate response status code
    assert response.status_code == expected_status_code, f"Unexpected status code: {response.status_code}"

    # Validate response schema
