    assert validation_result['valid'], f"Response validation failed: {validation_result.get('message', '')}"

    # Additional assertions based on scenario
    if expected_status_code == 200:
        assert 'order deleted' in response.json().get('description', ''), "Order deletion message not found"
    elif expected_status_code == 400:
        assert 'Invalid ID supplied' in response.json().get('description', ''), "Invalid ID message not found"
    elif expected_status_code == 404:
        assert 'Order not found' in response.json().get('description', ''), "Order not found message not found"
